let detailRequest=0;
const trialText=(value,fallback='Not reported')=>esc(value===undefined||value===null||value===''?fallback:value);
function trialLabel(s){return s.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,c=>c.toUpperCase())}
function resultTree(value){if(value===null||value===undefined)return '<span class="note">Not reported</span>';if(typeof value!=='object')return `<span>${esc(value)}</span>`;if(Array.isArray(value))return value.map((v,i)=>typeof v==='object'?`<details class="result-group"><summary>Entry ${i+1}${v.title?' · '+esc(v.title):''}</summary>${resultTree(v)}</details>`:`<p>${esc(v)}</p>`).join('')||'<span class="note">No entries reported</span>';return '<dl class="result-data">'+Object.entries(value).map(([k,v])=>`<div><dt>${esc(trialLabel(k))}</dt><dd>${resultTree(v)}</dd></div>`).join('')+'</dl>'}
function contactMarkup(c){return `<div class="contact-entry"><b>${trialText(c.name||c.role,'Study contact')}</b>${c.role&&c.name?' · '+esc(c.role):''}${c.phone?'<p>Phone: '+esc(c.phone)+(c.phoneExt?' ext. '+esc(c.phoneExt):'')+'</p>':''}${c.email?'<p>Email: '+esc(c.email)+'</p>':''}</div>`}
function trialDetailMarkup(s,{cached=false}={}){const p=s.protocolSection,id=p.identificationModule.nctId,status=p.statusModule||{},d=p.designModule||{},e=p.eligibilityModule||{},loc=p.contactsLocationsModule||{},a=p.armsInterventionsModule||{},out=p.outcomesModule||{};const section=(id,title,body)=>`<section class="detail-section" id="detail-${id}"><h3 class="section-rule">${title}</h3>${body}</section>`;const kv=(k,v)=>`<div><dt>${esc(k)}</dt><dd>${trialText(v)}</dd></div>`;let news=typeof researchNews!=='undefined'?researchNews.filter(n=>n.trial===id):[];return `<div class="eyebrow">DrugHorizons / Trial record / ${esc(id)}</div><h2 class="dialogtitle">${trialText(p.identificationModule.briefTitle)}</h2><span class="tag">${trialText(status.overallStatus?.replaceAll('_',' '))}</span> <span class="tag">${trialText((d.phases||[]).join(' / ').replaceAll('PHASE','Phase '))}</span><p class="note">${cached?'Registry refresh unavailable. Showing a previously fetched record; status may have changed.':'ClinicalTrials.gov record retrieved '+new Date().toLocaleString()+'.'} Registry update: ${trialText(status.lastUpdatePostDateStruct?.date)}.</p><nav class="detail-nav" aria-label="Trial sections">${['overview','eligibility','locations','design','results','sources'].map(t=>`<a href="#detail-${t}">${t[0].toUpperCase()+t.slice(1)}</a>`).join('')}</nav>${section('overview','Study overview',`<p class="preserve-lines">${trialText(p.descriptionModule?.briefSummary,'No summary reported.')}</p><dl class="detail-facts">${kv('Sponsor',p.sponsorCollaboratorsModule?.leadSponsor?.name)}${kv('Conditions',(p.conditionsModule?.conditions||[]).join(', '))}${kv('Study type',d.studyType)}${kv('Enrollment',d.enrollmentInfo?d.enrollmentInfo.count+' ('+(d.enrollmentInfo.type||'not specified').toLowerCase()+')':null)}${kv('Start date',status.startDateStruct?.date)}${kv('Primary completion',status.primaryCompletionDateStruct?.date)}</dl>${p.descriptionModule?.detailedDescription?'<details><summary>Detailed description</summary><p class="preserve-lines">'+esc(p.descriptionModule.detailedDescription)+'</p></details>':''}`)}${section('eligibility','Eligibility',`<dl class="detail-facts">${kv('Minimum age',e.minimumAge)}${kv('Maximum age',e.maximumAge)}${kv('Sex',e.sex)}${kv('Healthy volunteers',e.healthyVolunteers===undefined?undefined:e.healthyVolunteers?'Accepted':'Not accepted')}</dl><p class="preserve-lines">${trialText(e.eligibilityCriteria,'Detailed eligibility criteria are not reported.')}</p><p class="note">The study team confirms eligibility. These criteria do not determine an individual’s suitability automatically.</p>`)}${section('locations','Locations & contacts',`<h4>Central study contacts</h4>${(loc.centralContacts||[]).map(contactMarkup).join('')||'<p>No central contact reported.</p>'}<h4>Study sites (${(loc.locations||[]).length})</h4>${(loc.locations||[]).map(l=>`<details class="site-entry"><summary>${trialText(l.facility)} · ${esc([l.city,l.state,l.country].filter(Boolean).join(', '))}</summary><p>Site status: ${trialText(l.status?.replaceAll('_',' '))}</p><p>${esc([l.city,l.state,l.zip,l.country].filter(Boolean).join(', '))}</p>${(l.contacts||[]).map(contactMarkup).join('')||'<p class="note">No site contact reported.</p>'}</details>`).join('')||'<p>No locations reported in this record.</p>'}`)}${section('design','Design & interventions',`<dl class="detail-facts">${kv('Allocation',d.designInfo?.allocation)}${kv('Intervention model',d.designInfo?.interventionModel)}${kv('Primary purpose',d.designInfo?.primaryPurpose)}${kv('Masking',d.designInfo?.maskingInfo?.masking)}</dl>${(a.interventions||[]).map((v,i)=>`<div class="routebox"><span class="tag">${trialText(v.type)}</span><h4>${trialText(v.name)}</h4><p class="preserve-lines">${trialText(v.description,'No intervention description reported.')}</p>${v.type==='DRUG'?`<button class="outline" data-inspect-index="${i}">Inspect molecule in DrugHorizons</button>`:''}</div>`).join('')||'<p>No interventions reported.</p>'}${(a.armGroups||[]).map(v=>`<details><summary>${trialText(v.label)} · ${trialText(v.type)}</summary><p class="preserve-lines">${trialText(v.description)}</p></details>`).join('')}<h4>Registered outcome measures</h4>${[['Primary',out.primaryOutcomes],['Secondary',out.secondaryOutcomes]].map(([label,items])=>(items||[]).map(v=>`<div class="routebox"><span class="tag">${label}</span><h4>${trialText(v.measure)}</h4><p>${trialText(v.description,'No description reported.')}</p><p class="note">Time frame: ${trialText(v.timeFrame)}</p></div>`).join('')).join('')||'<p>No outcome measures reported.</p>'}`)}${section('results','Posted results',s.resultsSection?`<p class="note">Registry-reported results. Group identifiers, units, statistical analyses, and confidence limits are displayed as reported; missing fields are not estimated. Registered outcomes above are plans, not findings.</p>${Object.entries(s.resultsSection).map(([key,value])=>`<details class="result-group"><summary>${esc(trialLabel(key.replace(/Module$/,'')))}</summary>${resultTree(value)}</details>`).join('')}`:'<p>No posted results were returned in this registry record. A news report or publication may discuss findings before registry results are posted.</p>')}${section('sources','Sources & related reporting',`<p><a href="https://clinicaltrials.gov/study/${esc(id)}" target="_blank" rel="noopener">Original registry source (opens another website)</a></p>${news.map(n=>`<article class="routebox"><span class="tag">${esc(newsTypes[n.type])}</span><h4>${esc(n.title)}</h4><p class="note">${esc(n.publisher)} · ${esc(n.date)}</p><p>${esc(n.summary)}</p>${n.effect?'<p>'+esc(n.effect)+'</p>':''}<a href="${esc(n.url)}" target="_blank" rel="noopener">Original report (external source)</a></article>`).join('')}${(p.referencesModule?.references||[]).map(ref=>`<p>${trialText(ref.citation)}${/^\d+$/.test(ref.pmid||'')?` <a href="https://pubmed.ncbi.nlm.nih.gov/${ref.pmid}/" target="_blank" rel="noopener">Publication source</a>`:''}</p>`).join('')}`)}`}
async function details(id){if(!/^NCT\d{8}$/.test(id))return;const token=++detailRequest;showDialog('<div class="empty">Loading trial details in DrugHorizons…</div>');$('dialog').classList.add('trial-detail');const cached=[...studies,...saved].find(s=>s.protocolSection.identificationModule.nctId===id);let study,cachedOnly=false;try{const r=await fetch('https://clinicaltrials.gov/api/v2/studies/'+id,{signal:AbortSignal.timeout(16000)});if(!r.ok)throw Error();study=await r.json();if(study.protocolSection?.identificationModule?.nctId!==id)throw Error()}catch{study=cached;cachedOnly=true}if(token!==detailRequest||!$('dialog').open)return;if(!study){$('dialogbody').innerHTML='<h2>Trial unavailable</h2><p>The registry could not be reached and no local record is available.</p><button class="outline" id="retryDetail">Retry in DrugHorizons</button>';$('retryDetail').onclick=()=>details(id);return}$('dialogbody').innerHTML=trialDetailMarkup(study,{cached:cachedOnly});$('dialog').scrollTop=0;$('dialogbody').querySelectorAll('[data-inspect-index]').forEach(b=>b.onclick=()=>{const drug=study.protocolSection.armsInterventionsModule.interventions[Number(b.dataset.inspectIndex)];sessionStorage.setItem('dh-inspect-compound',drug.name);window.location.assign('/molecules/')})}
